script:
/* Global CSS complements native editable Builder styles; no visual sections depend on Vue. */
.school-portal-body{overflow-x:clip;font-family:"Noto Sans Bengali", "Hind Siliguri", sans-serif;}
.school-portal-body *{box-sizing:border-box}
.school-portal-body a:focus-visible,.school-portal-body button:focus-visible{outline:3px solid #E0A83E;outline-offset:2px}
.school-portal-body a:hover{color:#257c59}
.nav-scroll{scrollbar-width:thin;scrollbar-color:rgba(255,255,255,.45) transparent}
.nav-link:hover,.nav-link:focus-visible{background-color:rgba(5,36,26,.2);color:#fff!important}
.service-tile{transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease}
.service-tile:hover{transform:translateY(-3px);box-shadow:0 7px 23px rgba(22,51,75,.11);border-color:#9dcdb8}
.school-row-link:hover{background-color:#F3F8F6}
.notice-item[hidden]{display:none!important}
.notice-filter{cursor:pointer;transition:background-color .15s ease}
.notice-filter.is-active{background-color:#146344!important;color:white!important}
.campus-slide{isolation:isolate}
.news-card:hover,.feature-card:hover{box-shadow:0 6px 19px rgba(19,49,65,.075)}

@media(max-width:1100px){.info-grid{flex-wrap:wrap}.info-grid>.left-directory{flex:1 1 32%}.info-grid>.center-directory{flex:2 1 58%}.info-grid>.right-directory{flex:1 1 100%}.footer-grid{flex-wrap:wrap}}
@media(max-width:820px){.quick-services,.feature-grid,.gov-grid,.facility-grid,.gallery-grid{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))}.info-grid{display:flex;flex-wrap:wrap}.info-grid>.left-directory,.info-grid>.center-directory,.info-grid>.right-directory{flex:1 1 100%;width:100%}}
@media(max-width:576px){.school-portal-body{font-size:14px}.quick-services,.feature-grid,.gov-grid,.facility-grid,.gallery-grid{grid-template-columns:repeat(2,minmax(0,1fr))!important}.quick-services .service-tile{min-width:0}.stats-grid>div{min-width:42%;border:0!important}.footer-grid>div{min-width:43%}.ticker-line>a{display:none}.campus-slide{min-height:300px}.school-portal-body h1{font-size:22px!important}.school-portal-body h2{font-size:21px!important}}

/* Motion v2.1: original implementation inspired by inspected demo patterns.
   No section requires animation to render; no external JS/CSS/CDN dependency. */
.school-portal-body { scroll-behavior:smooth; }
.school-progress-bar { will-change:transform; }
.school-motion-toggle { transition:background-color .18s ease, border-color .18s ease; white-space:nowrap; }
.school-motion-toggle:hover { background-color:rgba(255,255,255,.17)!important; border-color:#fff!important; color:#fff!important; }
.school-motion-toggle:focus-visible { outline-offset:3px; }
.school-masthead-titles { min-width:0; }
.school-masthead-titles > * { opacity:1; }
/* The current notices stay visible: only offscreen sections are armed by JS. */
.school-reveal { opacity:1; }
.school-reveal.can-reveal { opacity:0; transform:translate3d(0,22px,0); transition:opacity .68s ease,transform .68s cubic-bezier(.2,.78,.22,1); }
.school-reveal.can-reveal[data-motion-variant="slide"] { transform:translate3d(-20px,0,0); }
.school-reveal.can-reveal[data-motion-variant="fade"] { transform:none; }
.school-reveal.can-reveal.is-shown { opacity:1; transform:none; }
/* Stagger group animates only when the observer finds that group visible. */
.school-stagger-group.is-inview > .service-tile,
.school-stagger-group.is-inview > .feature-card,
.school-stagger-group.is-inview > .news-card,
.school-stagger-group.is-inview > .gallery-photo-placeholder,
.school-stagger-group.is-inview > .gov-card { animation:school-card-arrive .62s cubic-bezier(.17,.76,.32,1) backwards; animation-delay:var(--school-stagger-delay,0ms); }
@keyframes school-card-arrive { from { opacity:.25; transform:translateY(14px) scale(.985); } to { opacity:1; transform:none; } }
/* Faint rule drawing creates structure without covering headings. */
.school-reveal h2::after { content:""; display:block; width:44px; height:2px; border-radius:3px; background:#D6A845; margin-top:5px; transform-origin:left center; transform:scaleX(1); }
.school-reveal.is-shown h2::after { animation:school-rule-draw .75s .1s cubic-bezier(.2,.8,.22,1) backwards; }
@keyframes school-rule-draw { from {transform:scaleX(0)} to {transform:scaleX(1)} }
/* Intro: short and subtle, never delays or hides notices. */
.school-masthead.is-inview .school-masthead-titles > :nth-child(1) { animation:school-head-settle .54s ease-out backwards; }
.school-masthead.is-inview .school-masthead-titles > :nth-child(2) { animation:school-head-settle .64s .06s ease-out backwards; }
.school-masthead.is-inview .school-masthead-titles > :nth-child(3) { animation:school-head-settle .64s .12s ease-out backwards; }
.school-masthead.is-inview .school-logo { animation:school-emblem-enter .78s cubic-bezier(.2,.9,.3,1) backwards; }
@keyframes school-head-settle { from {opacity:.35;transform:translateY(12px)} to {opacity:1;transform:none} }
@keyframes school-emblem-enter { from {opacity:.55;transform:scale(.87) rotate(-8deg)} to {opacity:1;transform:none} }
.school-hero-entrance.is-inview { animation:school-banner-enter .72s cubic-bezier(.2,.8,.25,1) both; }
@keyframes school-banner-enter { from { opacity:.6; filter:saturate(.86); transform:translateY(9px); } to { opacity:1;filter:none;transform:none;} }
/* Ambient glow on the static school banner; motion is offscreen-paused by observer. */
.school-campus-ambient { position:relative; overflow:hidden; }
.school-campus-ambient::before { content:""; position:absolute; inset:-50%; pointer-events:none; background:radial-gradient(circle at 40% 40%,rgba(238,201,110,.14),transparent 42%); transform:translate3d(0,0,0); opacity:.9; animation:school-campus-breathe 10s ease-in-out infinite alternate; }
.school-campus-ambient > * { position:relative; z-index:1; }
.school-campus-ambient.is-offscreen::before { animation-play-state:paused; }
@keyframes school-campus-breathe { to {transform:translate3d(4%, -2%,0);opacity:.38} }
/* Truly repeating marquee: JS duplicates a cycle, but keeps clones out of tab order. */
.ticker-line { position:relative; }
.ticker-line .ticker-track { width:max-content; will-change:transform; }
.ticker-track.is-looping { display:flex!important; gap:0!important; animation:school-ticker-loop var(--school-ticker-duration,28s) linear infinite; }
.ticker-cycle { flex:none; display:flex; gap:26px;align-items:center;padding-inline-end:26px;white-space:nowrap; }
@keyframes school-ticker-loop {to{transform:translate3d(-50%,0,0)}}
.ticker-line:hover .ticker-track,.ticker-line:focus-within .ticker-track,.ticker-track.is-offscreen { animation-play-state:paused; }
.notice-item.notice-enter {animation:school-notice-in .28s ease-out both;}
@keyframes school-notice-in {from{opacity:.55;transform:translateY(5px)}to{opacity:1;transform:none}}
/* Educational service cards: low-key interactions with useful focus affordances. */
.service-tile,.feature-card,.news-card,.gov-card,.gallery-photo-placeholder { transition:transform .24s ease,box-shadow .24s ease,filter .24s ease; }
.service-tile:hover,.feature-card:hover,.news-card:hover,.gov-card:hover {transform:translateY(-4px);box-shadow:0 11px 29px rgba(17,43,54,.12);}
.gallery-photo-placeholder {overflow:hidden;}
.gallery-photo-placeholder:hover {transform:translateY(-3px);filter:saturate(1.1) brightness(1.025)}
.school-row-link { position:relative; transition:background-color .16s ease,padding-left .16s ease; }
.school-row-link:hover { padding-left:8px; }
.school-motion-paused,.school-motion-paused *,.school-motion-paused *::before,.school-motion-paused *::after {scroll-behavior:auto!important;animation:none!important;transition:none!important;}
.school-motion-paused .school-reveal,.school-motion-paused .school-reveal.can-reveal {opacity:1!important;transform:none!important;}
.school-motion-paused .ticker-track {transform:none!important;}
@media(max-width:576px){
  .school-reveal.can-reveal[data-motion-variant="slide"]{transform:translate3d(0,14px,0)}
  .school-motion-toggle{padding:2px 5px!important;font-size:11px!important}
  .ticker-cycle{gap:15px;padding-inline-end:15px}
}
@media(prefers-reduced-motion:reduce){
  .school-portal-body,.school-portal-body *{scroll-behavior:auto!important}
  .school-portal-body *,.school-portal-body *::before,.school-portal-body *::after{animation:none!important;transition:none!important}
  .school-reveal.can-reveal{opacity:1!important;transform:none!important}
  .ticker-track{transform:none!important}
}
@media print{
 .school-portal-body *,.school-portal-body *::before,.school-portal-body *::after{animation:none!important;transition:none!important}
 .school-reveal.can-reveal{opacity:1!important;transform:none!important}
 .school-progress-bar,.school-motion-toggle{display:none!important}
}

/* Fallback: if animation is disabled, every ticker item remains reachable by horizontal scrolling. */
.school-motion-paused .school-ticker-viewport { overflow-x:auto!important; scrollbar-width:thin; }
@media(prefers-reduced-motion:reduce){.school-ticker-viewport { overflow-x:auto!important; scrollbar-width:thin; }}

/* Multi-page inner-page system */
.school-inner-page{background:#f7f9fb;color:#1f3448;min-height:100vh}
.school-inner-page .page-breadcrumb{background:#eef3f5;border-bottom:1px solid #e1e7ec}
.school-inner-page .page-breadcrumb a{color:#146344;text-decoration:none;font-weight:650}
.school-inner-page .page-hero{background:linear-gradient(115deg,#eef5f2 0%,#f7f9fb 65%,#edf3f7 100%);border-bottom:1px solid #e1e7ec}
.school-inner-page .page-card{box-shadow:0 1px 2px rgba(16,42,66,.025);transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease}
.school-inner-page .page-card:hover{border-color:#b8d4c8;box-shadow:0 7px 22px rgba(16,42,66,.07);transform:translateY(-2px)}
.school-inner-page .page-card-grid{display:flex;flex-wrap:wrap;align-items:stretch}
.school-inner-page .page-card-grid>.page-card{flex:1 1 28%;min-width:220px}
.school-inner-page .page-callout{border-left:4px solid #146344;background:#eef5f2}
.school-inner-page .page-list{background:#fff;border:1px solid #e1e7ec;border-radius:8px;padding:0 16px}
.school-inner-page .page-table{width:100%;border:1px solid #dfe7eb;border-radius:8px;overflow:hidden;background:#fff}
.school-inner-page .page-table-row{display:flex;gap:12px;padding:11px 14px;border-bottom:1px solid #e6ecef;align-items:center}
.school-inner-page .page-table-row:last-child{border-bottom:0}
.school-inner-page .page-table-head{background:#edf4f1;color:#16334b;font-weight:750}
.school-inner-page .page-aside{background:#fff;border:1px solid #e1e7ec;border-radius:8px;padding:17px}
.school-inner-page .page-aside a{display:block;padding:9px 0;border-bottom:1px solid #e7ecef;color:#1f3448;text-decoration:none;font-size:13px}
.school-inner-page .page-aside a:last-child{border-bottom:0}
.school-inner-page .page-aside a:hover{color:#146344}
.school-inner-page .page-kicker{color:#146344;text-transform:uppercase;letter-spacing:.08em;font-size:11px;font-weight:800}
.school-inner-page .page-timeline{border-left:2px solid #b7d4c6;margin-left:8px;padding-left:20px;display:flex;flex-direction:column;gap:14px}
.school-inner-page .page-timeline-item{position:relative;background:#fff;border:1px solid #e1e7ec;border-radius:8px;padding:14px}
.school-inner-page .page-timeline-item:before{content:'';position:absolute;width:10px;height:10px;border-radius:50%;background:#146344;left:-27px;top:18px;border:2px solid #fff}
.school-inner-page .page-faq-item{padding:15px;border:1px solid #e1e7ec;border-radius:8px;background:#fff}
.school-inner-page .page-faq-item h3{margin:0 0 7px;color:#16334b;font-size:15px}
.school-inner-page .nav-link.is-current{background:rgba(5,36,26,.24);box-shadow:inset 0 -3px 0 #f2c56d;color:#fff!important}
@media(max-width:900px){.school-inner-page .page-card-grid>.page-card{min-width:calc(50% - 10px)}.school-inner-page .page-table-row{flex-wrap:wrap}}
@media(max-width:600px){.school-inner-page .page-card-grid>.page-card{min-width:100%}.school-inner-page .page-table-row{gap:6px}.school-inner-page .page-aside{position:static!important}}
@media(prefers-reduced-motion:reduce){.school-inner-page .page-card{transition:none!important;transform:none!important}}
@media print{.school-inner-page .page-hero{background:#fff!important}.school-inner-page .page-card{box-shadow:none!important}}
